// Ported from the Node app's Sequelize model PerformanceReview (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class PerformanceReviewConfiguration : IEntityTypeConfiguration<PerformanceReview>
{
    public void Configure(EntityTypeBuilder<PerformanceReview> builder)
    {
        builder.ToTable("performance_reviews", t =>
        {
            t.HasCheckConstraint("CK_performance_reviews_status", "[status] IN (N'draft', N'final')");
        });
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.StaffId).HasColumnName("staff_id");
        builder.Property(e => e.Period).HasColumnName("period").HasColumnType("nvarchar(40)").HasMaxLength(40).IsRequired();
        builder.Property(e => e.ReviewDate).HasColumnName("review_date").HasColumnType("date");
        builder.Property(e => e.Reviewer).HasColumnName("reviewer").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.Property(e => e.Work).HasColumnName("work");
        builder.Property(e => e.Punctuality).HasColumnName("punctuality");
        builder.Property(e => e.Teamwork).HasColumnName("teamwork");
        builder.Property(e => e.Initiative).HasColumnName("initiative");
        builder.Property(e => e.Strengths).HasColumnName("strengths").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.Improvements).HasColumnName("improvements").HasColumnType("nvarchar(500)").HasMaxLength(500);
        builder.Property(e => e.Status).HasColumnName("status").HasColumnType("nvarchar(20)").IsRequired().HasDefaultValueSql("N'draft'");
        builder.HasOne(e => e.Staff).WithMany(p => p.PerformanceReviews).HasForeignKey(e => e.StaffId).OnDelete(DeleteBehavior.NoAction);
    }
}
